import axios from 'axios';

class UsersService {
	constructor() {
		this.app = axios.create({
			baseURL: process.env.REACT_APP_BASE_URL,
			withCredentials: true,
		});
	}

	getUsers = () => this.app.get('/all');
	updateProfile = profile_data => this.app.put('/user-profile', profile_data);
	updatePortfolio = portfolio_data => this.app.put('/user-portfolio', portfolio_data);
	getUser = user_id => this.app.get(`/${user_id}`);
}

export default UsersService;
