import { Nav, Navbar, NavDropdown } from 'react-bootstrap';
import { Link } from 'react-router-dom';
import AuthService from '../../../services/auth.service';
import './NavigationBar.css';
import { withRouter } from 'react-router-dom';
import logo from './logo.svg';

// import { useState, useEffect } from 'react'; 	// RESEARCH

const NavigationBar = ({ storeUser, loggedUser, history, setAlert }) => {
	const authService = new AuthService();

	// const [username, setUsername] = useState("") // RESEARCH
	// console.log(username) => ""
	// setUsername("teo")
	// console.log(username) => "teo"

	// useEffect(()=> {								// RESEARCH
	// console.log(username)
	// }, [])

	const logout = e => {
		e.preventDefault();

		authService
			.logout()
			.then(() => {
				storeUser(null);
				history.push('/');
			})
			.catch(err => setAlert(err.response.data.message));
	};

	return (
		<Navbar bg="dark" variant="dark" expand="md" style={{ padding: '10px 20px' }}>
			<Navbar.Brand href="/">
				<img alt="" src={logo} width="30" height="30" className="d-inline-block align-top" /> BaitBite
			</Navbar.Brand>
			<Navbar.Toggle aria-controls="basic-navbar-nav" />
			<Navbar.Collapse className="justify-content-end">
				<Nav className="mr-auto">
					{!loggedUser ? (
						<>
							<Link className="nav-link" to="/signup">
								Sign up
							</Link>
							<Link className="nav-link" to="/login">
								Log in
							</Link>
						</>
					) : (
						<>
							<Link className="nav-link" to="/explore">
								Explore
							</Link>

							<Link className="nav-link" to="/job-offers">
								Job offers
							</Link>

							<NavDropdown title="My profile" id="basic-nav-dropdown">
								<NavDropdown.Item as={Link} to="/my-profile">
									Profile
								</NavDropdown.Item>

								{loggedUser.role === 'ARTIST' && (
									<NavDropdown.Item as={Link} to="/my-gallery">
										My gallery
									</NavDropdown.Item>
								)}

								<NavDropdown.Item as={Link} to="/my-job-offers">
									My job offers
								</NavDropdown.Item>

								<NavDropdown.Divider />

								<NavDropdown.Item href="#" onClick={logout}>
									Log out
								</NavDropdown.Item>
							</NavDropdown>
						</>
					)}
				</Nav>
			</Navbar.Collapse>
		</Navbar>
	);
};

//HOC
export default withRouter(NavigationBar);
