import axios from 'axios';

class PortfolioService {
	constructor() {
		this.app = axios.create({
			baseURL: process.env.REACT_APP_BASE_URL,
			withCredentials: true,
		});
	}

	getImages = (limit, filter) => (limit ? this.app.get(`/all/limit-${limit}`) : this.app.get(`/all${filter}`));
	getMyImages = () => this.app.get(`/all/currentArtist`);
	getUserImages = user_id => this.app.get(`/all/${user_id}`);
	saveImage = image_data => this.app.post('/portfolio-image', image_data);
	getImage = image_id => this.app.get(`/${image_id}`);
	updateImage = (image_id, image_data) => this.app.put(`/${image_id}`, image_data);
	likeImage = (image_id, liked) => (liked ? this.app.put(`/${image_id}/dislike`) : this.app.put(`/${image_id}/like`));
	dislikeImage = image_id => this.app.put(`/${image_id}/dislike`);
	deleteImage = image_id => this.app.delete(`/${image_id}`);
}

export default PortfolioService;
