import { Toast } from 'react-bootstrap';
import logo from './logo.svg';
import './GlobalAlert.css';

const GlobalAlert = ({ show, message, closeAlert }) => {
	return (
		<Toast show={show} delay={3000} onClose={closeAlert} autohide className="global-alert-toast" bg="warning">
			<Toast.Header closeButton={false}>
				<img src={logo} width="20" height="20" className="rounded me-2" alt="" />
				<strong className="me-auto">Alert!</strong>
				<small>{new Date(Date.now()).toUTCString()}</small>
			</Toast.Header>
			<Toast.Body>{message}</Toast.Body>
		</Toast>
	);
};

export default GlobalAlert;
