import { Component } from 'react';
import { Container, Form } from 'react-bootstrap';
import './Searchbox.css';

class Searchbox extends Component {
	constructor() {
		super();

		this.state = {
			filter: '',
		};
	}

	handleInputChange = e => {
		let filter;
		e.target.value.match(/^\s*$/) ? (filter = '') : (filter = `?filter=${e.target.value.trim()}`);

		this.setState({ filter: e.target.value }, () => this.props.updateFilter(filter));
	};

	render = () => (
		<>
			<Container className="searchbox">
				<Form onSubmit={this.handleFormSubmit}>
					<Form.Group controlId="filter">
						<Form.Label>Search</Form.Label>
						<Form.Control type="text" value={this.state.filter} onChange={this.handleInputChange} name="filter" />
					</Form.Group>
				</Form>
			</Container>
		</>
	);
}

export default Searchbox;
