import { Component } from 'react';
import { Button, Col, Container, Form, Modal, Row } from 'react-bootstrap';
import { Link } from 'react-router-dom';
import EditProfileForm from './EditProfileForm';
import Portfolio from './Portfolio';
import './MyProfile.css';

class MyProfile extends Component {
	constructor() {
		super();

		this.state = {
			modal: false,
		};
	}

	openProfileForm = () => this.setState({ modal: true });

	render = () => (
		<Container>
			{this.props.loggedUser && (
				<>
					<Row>
						<Button as={Link} to="/" variant="light" className="col-md-4" style={{ border: '2px solid black' }}>
							Go back
						</Button>
					</Row>

					<hr />

					{this.props.loggedUser.role === 'ARTIST' && (
						<>
							<Row>
								<Col md={{ span: 6, offset: 4 }}>
									<Button as={Link} to="/my-gallery" variant="dark full-width">
										Go to MyGallery
									</Button>
								</Col>
							</Row>

							<hr />
						</>
					)}

					<Form.Group as={Row} className="mb-3">
						<Form.Label column sm={{ span: 2, offset: 2 }}>
							Username
						</Form.Label>
						<Col sm="6">
							<Form.Control
								plaintext
								readOnly
								value={this.props.loggedUser.username}
								className="profile-info-field"
							/>
						</Col>
						<Form.Label column sm={{ span: 2, offset: 2 }}>
							Password
						</Form.Label>
						<Col sm="6">
							<Form.Control type="password" plaintext readOnly value="••••••••" className="profile-info-field" />
							<Button variant="dark" onClick={this.openProfileForm} className="full-width">
								Edit login
							</Button>
						</Col>
					</Form.Group>

					<Modal show={this.state.modal} onHide={() => this.setState({ modal: false })} centered>
						<Modal.Header>
							<Modal.Title>Edit user login info</Modal.Title>
						</Modal.Header>

						<Modal.Body>
							<EditProfileForm
								loggedUser={this.props.loggedUser}
								storeUser={this.props.storeUser}
								closeModal={() => this.setState({ modal: false })}
								setAlert={this.props.setAlert}
							/>
						</Modal.Body>
					</Modal>

					<hr />

					{this.props.loggedUser.role === 'ARTIST' && (
						<Portfolio
							loggedUser={this.props.loggedUser}
							self={true}
							storeUser={this.props.storeUser}
							setAlert={this.props.setAlert}
						/>
					)}
				</>
			)}
		</Container>
	);
}

export default MyProfile;
