import { Component } from 'react';
import { Container, Modal, Row } from 'react-bootstrap';
import JobOffersService from '../../../services/jobOffer.service';
import JobOfferDetails from './JobOfferDetails';
import JobOfferItem from './JobOfferItem';
import NewJobOfferForm from './NewJobOfferForm';

class JobOfferList extends Component {
	constructor() {
		super();

		this.state = {
			jobOffers: undefined,
			job_id: undefined,
			modal: false,
			newJobModal: false,

			filter: '',
		};

		this.jobOffersService = new JobOffersService();
	}

	loadJobOffers = (self, limit) => {
		self
			? this.props.loggedUser.role === 'ARTIST'
				? this.jobOffersService
						.getMyApplied()
						.then(response => this.setState({ jobOffers: response.data }))
						.catch(err => this.props.setAlert(err.response.data.message))
				: this.jobOffersService
						.getMyCreated()
						.then(response => this.setState({ jobOffers: response.data }))
						.catch(err => this.props.setAlert(err.response.data.message))
			: this.jobOffersService
					.getJobOffers(this.state.filter)
					.then(response => this.setState({ jobOffers: response.data }))
					.catch(err => this.props.setAlert(err.response.data.message));
	};

	componentDidMount = () => {
		this.setState({ filter: this.props.filter });

		this.loadJobOffers(this.props.self, this.props.limit, this.state.filter);
	};

	openDetails = job_id => {
		this.setState({ job_id, modal: true });
	};

	refreshList = () => this.loadJobOffers(this.props.self, this.props.limit, this.state.filter);

	componentDidUpdate = () => {
		this.props.filter !== this.state.filter && this.setState({ filter: this.props.filter }, () => this.refreshList());
	};

	render = () => (
		<Container>
			{this.props.loggedUser.role === 'RECRUITER' && (
				<Row className="justify-content-center" style={{ marginBottom: 30 }}>
					<button onClick={() => this.setState({ newJobModal: true })} className="col-auto btn add-img-btn">
						<div className="content">
							<span className="icon-plus"></span>
						</div>
					</button>
				</Row>
			)}

			<Row className="g-2">
				{this.state.jobOffers?.map(el => (
					<JobOfferItem
						key={el._id}
						id={el._id}
						brand={el.brand}
						title={el.title}
						description={el.description}
						openDetails={this.openDetails}
					/>
				))}
			</Row>

			<Modal
				show={this.state.modal}
				onHide={() => this.setState({ image_id: undefined, modal: false })}
				dialogClassName="modal-80w"
				centered
			>
				<JobOfferDetails
					loggedUser={this.props.loggedUser}
					refreshList={this.refreshList}
					job_id={this.state.job_id}
					closeModal={() => this.setState({ job_id: undefined, modal: false })}
					setAlert={this.props.setAlert}
				/>
			</Modal>

			<Modal show={this.state.newJobModal} onHide={() => this.setState({ newJobModal: false })} centered>
				<Modal.Header>
					<Modal.Title>New job offer</Modal.Title>
				</Modal.Header>

				<Modal.Body>
					<NewJobOfferForm
						refreshList={this.refreshList}
						closeModal={() => this.setState({ ...this.state, newJobModal: false })}
						setAlert={this.props.setAlert}
					/>
				</Modal.Body>
			</Modal>
		</Container>
	);
}

export default JobOfferList;
