import axios from 'axios';

class JobOffersService {
	constructor() {
		this.app = axios.create({
			baseURL: process.env.REACT_APP_BASE_URL,
			withCredentials: true,
		});
	}

	getJobOffers = filter => this.app.get(`/all${filter}`);
	getMyApplied = () => this.app.get('/all/applied');
	getMyCreated = () => this.app.get('/all/created');
	getUserApplied = user_id => this.app.get(`/all/applied/${user_id}`);
	getUserCreated = user_id => this.app.get(`/all/created/${user_id}`);
	saveJobOffer = job_data => this.app.post('/job-offer', job_data);
	getJobOffer = job_id => this.app.get(`/${job_id}`);
	updateJobOffer = (job_id, job_data) => this.app.put(`/${job_id}`, job_data);
	applyJobOffer = (job_id, applied) => (applied ? this.app.put(`/${job_id}/quit`) : this.app.put(`/${job_id}/apply`));
	// quitJobOffer = job_id => this.app.put(`/${job_id}/quit`);
	deleteJobOffer = job_id => this.app.delete(`/${job_id}`);
}

export default JobOffersService;
