import { Component } from 'react';
import { Button, Col, Container, Form, Modal, Row } from 'react-bootstrap';
import UsersService from '../../../services/users.service';
import EditPortfolioForm from './EditPortfolioForm';
import './Portfolio.css';

class Portfolio extends Component {
	constructor() {
		super();

		this.state = {
			portfolio: undefined,
			modal: false,
		};

		this.usersService = new UsersService();
	}

	componentDidMount = () => {
		this.props.self
			? this.setState({
					portfolio: this.props.loggedUser.portfolio,
					modal: false,
			  })
			: this.loadPortfolio(this.props.artist_id);
	};

	loadPortfolio = artist_id => {
		this.usersService
			.getUser(artist_id)
			.then(response => this.setState({ portfolio: response.data.portfolio }))
			.catch(err => this.props.setAlert(err.response.data.message));
	};

	openPortfolioForm = () => this.setState({ modal: true });

	refreshPortfolio = user => {
		this.setState({
			portfolio: this.props.loggedUser.portfolio,
			modal: false,
		});
	};

	render = () => (
		<Container>
			{this.props.loggedUser && this.state.portfolio && (
				<>
					<Form.Group as={Row} className="mb-3">
						<Form.Label column sm={{ span: 2, offset: 2 }}>
							Name
						</Form.Label>
						<Col sm="6">
							<Form.Control plaintext readOnly value={this.state.portfolio.name} className="portfolio-info-field" />
						</Col>

						<Form.Label column sm={{ span: 2, offset: 2 }}>
							Last name
						</Form.Label>
						<Col sm="6">
							<Form.Control
								plaintext
								readOnly
								value={this.state.portfolio.last_name}
								className="portfolio-info-field"
							/>
						</Col>
					</Form.Group>

					<hr />

					<Form.Group as={Row} className="mb-3">
						<Form.Label column sm={{ span: 2, offset: 2 }}>
							Country
						</Form.Label>
						<Col sm="6">
							<Form.Control
								plaintext
								readOnly
								value={this.state.portfolio.country}
								className="portfolio-info-field"
							/>
						</Col>

						<Form.Label column sm={{ span: 2, offset: 2 }}>
							City
						</Form.Label>
						<Col sm="6">
							<Form.Control plaintext readOnly value={this.state.portfolio.city} className="portfolio-info-field" />
						</Col>
					</Form.Group>

					<hr />

					<Form.Group as={Row} className="mb-3">
						<Form.Label column sm={{ span: 2, offset: 2 }}>
							Email
						</Form.Label>
						<Col sm="6">
							<Form.Control
								plaintext
								readOnly
								value={this.state.portfolio.email}
								className="portfolio-info-field"
							/>
						</Col>

						<Form.Label column sm={{ span: 2, offset: 2 }}>
							Tel.
						</Form.Label>
						<Col sm="6">
							<Form.Control plaintext readOnly value={this.state.portfolio.tel} className="portfolio-info-field" />
						</Col>
					</Form.Group>

					<hr />

					<Form.Group as={Row} className="mb-3">
						<Form.Label column sm={{ span: 2, offset: 2 }}>
							About
						</Form.Label>
						<Col sm="6">
							<Form.Control
								as="textarea"
								plaintext
								readOnly
								value={this.state.portfolio.about}
								className="portfolio-info-field"
							/>
						</Col>

						<Form.Label column sm={{ span: 2, offset: 2 }}>
							Experience
						</Form.Label>
						<Col sm="6">
							{this.state.portfolio.experience.map((el, i) => (
								<Form.Control plaintext readOnly key={i} value={String(el)} className="portfolio-info-field" />
							))}
						</Col>
					</Form.Group>

					<hr />

					<Form.Group as={Row} style={{ marginBottom: 40 }}>
						<Form.Label column sm={{ span: 2, offset: 2 }}>
							Tags
						</Form.Label>
						<Col sm="6">
							{this.state.portfolio.tags.map((el, i) => (
								<span key={i} className="portfolio-tag-item">
									{String(el)}
								</span>
							))}
						</Col>
					</Form.Group>

					{this.props.self && (
						<>
							<Button variant="dark" onClick={this.openPortfolioForm} className="full-width">
								Edit portfolio
							</Button>

							<Modal show={this.state.modal} onHide={() => this.setState({ ...this.state, modal: false })} centered>
								<Modal.Header>
									<Modal.Title>Portfolio</Modal.Title>
								</Modal.Header>

								<Modal.Body>
									<EditPortfolioForm
										loggedUser={this.props.loggedUser}
										storeUser={this.props.storeUser}
										refreshPortfolio={this.refreshPortfolio} // FIX - Probably no need to refresh if we update loggedUser with storeUser
										closeModal={() => this.setState({ ...this.state, modal: false })}
										setAlert={this.props.setAlert}
									/>
								</Modal.Body>
							</Modal>
						</>
					)}
				</>
			)}
		</Container>
	);
}

export default Portfolio;
