import { Component } from 'react';
import { Button, Col, Container, Form, Modal, Row } from 'react-bootstrap';
import { Link } from 'react-router-dom';
import JobOffersService from '../../../services/jobOffer.service';
import './JobOfferDetails.css';

class JobOfferDetails extends Component {
	constructor() {
		super();

		this.state = {
			jobOffer: undefined,
			applied: false,
			tagInput: false,
			titleInput: false,
			brandInput: false,
			descriptionInput: false,
			showDelete: false,

			// Edit inputs only
			brand: '',
			title: '',
			description: '',
			tags: '',
		};

		this.jobOffersService = new JobOffersService();
	}

	componentDidMount = () => {
		this.jobOffersService
			.getJobOffer(this.props.job_id)
			.then(response => {
				const applicants = [...response.data.applicants];

				const applied =
					this.props.loggedUser &&
					this.props.loggedUser.role === 'ARTIST' &&
					applicants.some(applicant => applicant._id === this.props.loggedUser._id);

				this.setState({
					jobOffer: response.data,
					applied,

					brand: response.data.brand,
					title: response.data.title,
					description: response.data.description,
				});
			})
			.catch(err => this.props.setAlert(err.response.data.message));
	};

	updateApplicants = () => {
		this.jobOffersService
			.applyJobOffer(this.state.jobOffer._id, this.state.applied)
			.then(response => {
				const applied = this.props.loggedUser && response.data.applicants.includes(String(this.props.loggedUser._id));
				this.setState({
					jobOffer: {
						...this.state.jobOffer,
						applicants: response.data.liked,
					},

					applied,
				});
			})
			.catch(err => this.props.setAlert(err.response.data.message));
	};

	deleteJobOffer = () => {
		this.jobOffersService
			.deleteJobOffer(this.state.jobOffer._id)
			.then(() => {
				this.setState({
					jobOffer: undefined,
				});
				this.props.refreshList();
				this.props.closeModal();
			})
			.catch(err => this.props.setAlert(err.response.data.message));
	};

	deleteTag = index => {
		const tags = [...this.state.jobOffer.tags];
		tags.splice(index, 1);

		this.jobOffersService
			.updateJobOffer(this.state.jobOffer._id, { ...this.state.jobOffer, tags })
			.then(response => this.setState({ jobOffer: response.data }))
			.catch(err => this.props.setAlert(err.response.data.message));
	};

	handleInputChange = e => {
		let { name, value } = e.target;
		this.setState({ [name]: value });
	};

	handleInputSubmit = e => {
		e.preventDefault();

		const tags = this.state.jobOffer.tags.concat(this.state.tags.split(/,\s*/));

		this.jobOffersService
			.updateJobOffer(this.state.jobOffer._id, {
				brand: this.state.brand,
				title: this.state.title,
				description: this.state.description,
				tags,
			})
			.then(response => {
				this.setState({
					jobOffer: response.data,
					tagInput: false,
					titleInput: false,
					brandInput: false,
					descriptionInput: false,
					tags: '',
				});

				this.props.refreshList();
			})
			.catch(err => this.props.setAlert(err.response.data.message));
	};

	render = () => (
		<>
			{this.state.jobOffer && (
				<>
					<Modal.Header>
						<Container className="job-details">
							<Row className="justify-content-between align-items-center">
								<Col>
									<h2 style={{ fontWeight: 400, fontStyle: 'oblique' }}>
										{!this.state.titleInput ? this.state.jobOffer.title : <span>Edit title:</span>}
										{this.state.jobOffer.recruiter_id === this.props.loggedUser?._id && (
											<>
												<Button
													variant="transparent"
													className="edit-btn"
													onClick={() => this.setState({ titleInput: !this.state.titleInput })}
												>
													<span className="icon-edit">{/* Edit */}</span>
												</Button>

												<Form
													onSubmit={this.handleInputSubmit}
													hidden={!this.state.titleInput}
													className="add-tags-form"
												>
													<Form.Group controlId="title">
														<Form.Control
															type="text"
															value={this.state.title}
															onChange={this.handleInputChange}
															name="title"
														/>
													</Form.Group>

													<Button
														style={{ marginTop: '20px', width: '100%' }}
														variant="dark"
														type="submit"
													>
														Save
													</Button>
												</Form>
											</>
										)}
									</h2>

									<div style={{ fontWeight: 400, fontStyle: 'oblique', margin: '20px auto' }}>
										<span style={{ fontWeight: 100, fontStyle: 'normal' }}>For: </span>
										{!this.state.brandInput ? this.state.jobOffer.brand : <span>Edit brand:</span>}

										{this.state.jobOffer.recruiter_id === this.props.loggedUser?._id && (
											<>
												<Button
													variant="transparent"
													className="edit-btn"
													onClick={() => this.setState({ brandInput: !this.state.brandInput })}
												>
													<span className="icon-edit">{/* Edit */}</span>
												</Button>

												<Form
													onSubmit={this.handleInputSubmit}
													hidden={!this.state.brandInput}
													className="add-tags-form"
												>
													<Form.Group controlId="brand">
														<Form.Label>Brand</Form.Label>
														<Form.Control
															type="text"
															value={this.state.brand}
															onChange={this.handleInputChange}
															name="brand"
														/>
													</Form.Group>

													<Button
														style={{ marginTop: '20px', width: '100%' }}
														variant="dark"
														type="submit"
													>
														Save
													</Button>
												</Form>
											</>
										)}
									</div>

									<div className="tags">
										<label>Tags:</label>
										{this.state.jobOffer.tags.map((tag, i) => (
											<span key={i} className="tag-item">
												{tag}
												{this.state.jobOffer.recruiter_id === this.props.loggedUser?._id && (
													<Button className="delete-tag-btn" onClick={() => this.deleteTag(i)}>
														<span className="icon-plus small-icon"></span>
													</Button>
												)}
											</span>
										))}

										{this.state.jobOffer.recruiter_id === this.props.loggedUser?._id && (
											<>
												<span
													as={Button}
													style={{
														transform: this.state.tagInput && 'rotate(45deg) scale(1.5)',
														backgroundColor: this.state.tagInput && 'transparent',
														borderRadius: this.state.tagInput && '50%',
													}}
													className="add-tag-btn tag-item icon-plus small-icon"
													onClick={() => this.setState({ tagInput: !this.state.tagInput })}
												></span>

												<Form
													onSubmit={this.handleInputSubmit}
													hidden={!this.state.tagInput}
													className="add-tags-form"
												>
													<Form.Group controlId="tags">
														<Form.Label>New tags (comma separated)</Form.Label>
														<Form.Control
															type="textarea"
															value={this.state.tags}
															onChange={this.handleInputChange}
															name="tags"
															placeholder="First, second, third..."
														/>
													</Form.Group>

													<Button
														style={{ marginTop: '20px', width: '100%' }}
														variant="dark"
														type="submit"
													>
														Add tags
													</Button>
												</Form>
											</>
										)}
									</div>
								</Col>

								{this.props.loggedUser && this.props.loggedUser?.role === 'ARTIST' && (
									<Col xs={2} className="like-btn-col">
										<Button variant="transparent" onClick={this.updateApplicants}>
											{this.state.applied ? (
												<span className="icon-heart"></span>
											) : (
												<span className="icon-plus-circled"></span>
											)}
										</Button>
									</Col>
								)}

								{this.state.jobOffer.recruiter_id === this.props.loggedUser?._id && (
									<Col xs={2} className="delete-btn-col">
										<Button variant="warning" className="delete-btn" onClick={this.deleteJobOffer}>
											<span className="icon-trash-empty">{/* Delete */}</span>
										</Button>
									</Col>
								)}
							</Row>
						</Container>
					</Modal.Header>

					<Modal.Body className="full-width no-padding">
						<Container fluid className="job-details no-padding">
							<Row>
								<Col xs={12}>
									<p className="job-description">
										{this.state.jobOffer.description}

										{this.state.jobOffer.recruiter_id === this.props.loggedUser?._id && (
											<Button
												variant="transparent"
												className="edit-btn"
												onClick={() => this.setState({ descriptionInput: !this.state.descriptionInput })}
											>
												<span className="icon-edit">{/* Edit */}</span>
											</Button>
										)}
									</p>

									{this.state.jobOffer.recruiter_id === this.props.loggedUser?._id && (
										<Container>
											<Form
												onSubmit={this.handleInputSubmit}
												hidden={!this.state.descriptionInput}
												className="add-tags-form"
											>
												<Form.Group controlId="description">
													<Form.Label>Description</Form.Label>
													<Form.Control
														type="textarea"
														value={this.state.description}
														onChange={this.handleInputChange}
														name="description"
														autoFocus
													/>
												</Form.Group>

												<Button
													style={{ margin: '20px auto', width: '100%' }}
													variant="dark"
													type="submit"
												>
													Save
												</Button>
											</Form>
										</Container>
									)}
								</Col>

								{this.state.jobOffer.recruiter_id === this.props.loggedUser?._id && (
									<>
										<Col xs={12}>
											<hr />

											<div style={{ margin: '25px 30px' }}>
												<label>Applicants:</label>
												{this.state.jobOffer.applicants.map((artist, i) => (
													<span key={i} className="tag-item">
														<Link to={`/portfolio/${artist._id}`}>
															{artist.portfolio.name} {artist.portfolio.last_name}
														</Link>
													</span>
												))}
											</div>
										</Col>
									</>
								)}
							</Row>
						</Container>
					</Modal.Body>
				</>
			)}
		</>
	);
}

export default JobOfferDetails;
