import { Component } from 'react';
import { Form, Button, Container } from 'react-bootstrap';
import UsersService from '../../../services/users.service';

class EditProfileForm extends Component {
	constructor() {
		super();

		this.state = {
			username: '',
			oldPassword: '',
			newPassword: '',
		};

		this.usersService = new UsersService();
	}

	handleInputChange = e => {
		const { name, value } = e.target;
		this.setState({ [name]: value });
	};

	handleFormSubmit = e => {
		e.preventDefault();

		this.usersService
			.updateProfile(this.state)
			.then(response => {
				this.props.closeModal();
				this.props.storeUser(response.data);
				this.setState({ username: '', oldPassword: '', newPassword: '' });
			})
			.catch(err => this.props.setAlert(err.response.data.message));
	};

	render() {
		return (
			<Container>
				<Form onSubmit={this.handleFormSubmit}>
					<Form.Group controlId="username">
						<Form.Label>Username</Form.Label>
						<Form.Control type="text" value={this.state.username} onChange={this.handleInputChange} name="username" />
					</Form.Group>

					<Form.Group controlId="oldPassword">
						<Form.Label>Old password</Form.Label>
						<Form.Control
							type="password"
							value={this.state.oldPassword}
							onChange={this.handleInputChange}
							name="oldPassword"
						/>
					</Form.Group>

					<Form.Group controlId="newPassword">
						<Form.Label>New password</Form.Label>
						<Form.Control
							type="password"
							value={this.state.newPassword}
							onChange={this.handleInputChange}
							name="newPassword"
						/>
					</Form.Group>

					<Button style={{ marginTop: '20px', width: '100%' }} variant="dark" type="submit">
						Update login info
					</Button>
				</Form>
			</Container>
		);
	}
}

export default EditProfileForm;
