import { Component } from 'react';
import { Container, Modal, Row } from 'react-bootstrap';
import PortfolioService from '../../../services/portfolio.service';
import NewImageForm from '../Profile/NewImageForm';
import PortfolioImageDetails from './PortfolioImageDetails';
import PortfolioImageItem from './PortfolioImageItem';
import './PortfolioImageList.css';

class PortfolioImageList extends Component {
	constructor() {
		super();

		this.state = {
			images: undefined,
			image_id: undefined,
			modal: false,
			newImageModal: false,

			filter: '',
		};

		this.portfolioService = new PortfolioService();
	}

	loadImages = (self, limit, filter) => {
		self
			? this.portfolioService
					.getMyImages()
					.then(response => this.setState({ images: response.data }))
					.catch(err => this.props.setAlert(err.response.data.message))
			: this.portfolioService
					.getImages(limit, filter)
					.then(response => this.setState({ images: response.data }))
					.catch(err => this.props.setAlert(err.response.data.message));
	};

	componentDidMount = () => {
		this.setState({ filter: this.props.filter });

		this.loadImages(this.props.self, this.props.limit, this.state.filter);
	};

	openDetails = image_id => {
		this.setState({ image_id, modal: true });
	};

	refreshList = () => this.loadImages(this.props.self, this.props.limit, this.state.filter);

	componentDidUpdate = () => {
		this.props.filter !== this.state.filter && this.setState({ filter: this.props.filter }, () => this.refreshList());
	};

	render = () => (
		<Container>
			{this.props.self && (
				<Row className="justify-content-center" style={{ marginBottom: 30 }}>
					<button onClick={() => this.setState({ newImageModal: true })} className="col-auto btn add-img-btn">
						<div className="content">
							<span className="icon-plus"></span>
						</div>
					</button>
				</Row>
			)}

			<Row className="g-2">
				{this.state.images?.map(el => (
					<PortfolioImageItem
						key={el._id}
						id={el._id}
						img_url={el.img_url}
						openDetails={this.openDetails}
						limit={this.props.limit}
					/>
				))}
			</Row>

			<Modal
				show={this.state.modal}
				onHide={() => this.setState({ image_id: undefined, modal: false })}
				dialogClassName="modal-80w"
				centered
			>
				<PortfolioImageDetails
					loggedUser={this.props.loggedUser}
					refreshList={this.refreshList}
					image_id={this.state.image_id}
					closeModal={() => this.setState({ image_id: undefined, modal: false })}
					setAlert={this.props.setAlert}
				/>
			</Modal>

			<Modal show={this.state.newImageModal} onHide={() => this.setState({ newImageModal: false })} centered>
				<Modal.Header>
					<Modal.Title>New portfolio image</Modal.Title>
				</Modal.Header>

				<Modal.Body>
					<NewImageForm
						refreshList={this.refreshList}
						closeModal={() => this.setState({ ...this.state, newImageModal: false })}
						setAlert={this.props.setAlert}
					/>
				</Modal.Body>
			</Modal>
		</Container>
	);
}

export default PortfolioImageList;
